mapper.select:
SELECT p.name AS platformName, c.rate as channelPayRate, c.name AS channelName, t.platform_id as platformId, t.channel_id as channelId, SUM(t.money) AS money, SUM(t.real_money) AS realMoney, t.update_time as updateTime FROM member_recharge_online t LEFT JOIN pay_channel c ON t.channel_id = c.id LEFT JOIN pay_platform p ON t.platform_id = p.id where t.status = 1
and t.platform_id = #{platformId}
and t.update_time >= #{selectStartDate} and t.update_time <= #{selectEndDate}
and t.channel_id in (SELECT id from pay_channel where name like concat(#{channelName}, '%'))
GROUP BY t.channel_id, t.platform_id

SELECT SUM(t.real_money) AS realMoney, SUM(t.real_money * c.rate) AS handlingfeeTotal, t.platform_id, t.channel_id, t.update_time, COUNT(*) AS totalcount FROM member_recharge_online t LEFT JOIN pay_channel c ON t.channel_id = c.id WHERE t.status = 1
and t.platform_id = #{platformId}
and t.update_time >= #{selectStartDate} and t.update_time <= #{selectEndDate}
and t.channel_id in (SELECT id from pay_channel where name like concat(#{channelName}, '%'))
